begin;create extension if not exists pgtap with schema extensions;select plan(39);
select has_table('public','platform_admins','platform admin roles exist');select has_table('public','reports','reports exist');select has_table('public','moderation_cases','cases exist');select has_table('public','sanctions','sanctions exist');select has_table('public','support_tickets','support exists');select has_table('public','tournament_rule_versions','rules versions exist');select has_table('public','platform_config','config exists');
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select ok(public.is_platform_admin(),'seeded super admin recognized');select ok(public.is_platform_moderator(),'super admin inherits moderator');select ok(public.is_support_agent(),'super admin has operational support access');
select lives_ok($$select public.manage_platform_admin('00000000-0000-4000-8000-000000000004','platform_moderator',true)$$,'super admin grants role');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);select ok(public.is_platform_moderator(),'granted moderator active');select throws_ok($$select public.manage_platform_admin('00000000-0000-4000-8000-000000000005','support_agent',true)$$,'42501',null,'moderator cannot grant roles');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);select throws_ok($$select public.issue_sanction('00000000-0000-4000-8000-000000000006',null,null,'platform','ban','bad',null)$$,'42501',null,'ordinary user cannot ban');
select lives_ok($$select public.create_report('00000000-0000-4000-8000-000000000006',null,null,'harassment','conduct','Detailed report description',null)$$,'user creates report');select is((select count(*)from public.reports),1::bigint,'reporter reads own report');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);select is((select count(*)from public.reports),0::bigint,'reported user cannot read report or reporter');
select lives_ok($$select public.create_support_ticket('technical','Help','Public support message')$$,'user creates ticket');select is((select count(*)from public.support_tickets),1::bigint,'requester reads own ticket');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);select ok(public.is_support_agent(),'support role recognized');select is((select count(*)from public.support_tickets),1::bigint,'support reads queue');insert into public.support_ticket_messages(ticket_id,author_user_id,message,is_internal)select id,'00000000-0000-4000-8000-000000000003','internal',true from public.support_tickets;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);select is((select count(*)from public.support_ticket_messages where is_internal),0::bigint,'internal support note hidden');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);select lives_ok($$select public.publish_rule_version('10000000-0000-4000-8000-000000000001','Rules v1',true)$$,'publish v1');select lives_ok($$select public.publish_rule_version('10000000-0000-4000-8000-000000000001','Rules v2',true)$$,'publish v2');select is((select count(*)from public.tournament_rule_versions),2::bigint,'new version preserves old');update public.tournament_rule_versions set content='rewrite';select is((select count(*)from public.tournament_rule_versions where content='rewrite'),0::bigint,'rule versions immutable to client');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);select lives_ok($$select public.accept_tournament_rules('10000000-0000-4000-8000-000000000001',(select id from public.tournament_rule_versions where version=1))$$,'accept exact v1');select ok(not exists(select 1 from public.rule_acceptances where user_id='00000000-0000-4000-8000-000000000005'and rule_version_id=(select active_rule_version_id from public.tournaments where id='10000000-0000-4000-8000-000000000001')),'new rule requires acceptance');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);select lives_ok($$select public.set_platform_config('maintenance_mode','true','CONFIRM')$$,'super admin enables maintenance');select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);select throws_ok($$insert into public.tournament_players(tournament_id,user_id,ign,rating_status,registration_status)values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000005','maintenance','pending','draft')$$,'P0001','MAINTENANCE_MODE','normal mutation blocked');select lives_ok($$select * from public.public_tournament_summary$$,'public read survives maintenance');select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);select lives_ok($$select public.set_platform_config('maintenance_mode','false','CONFIRM')$$,'maintenance disabled');
select lives_ok($$select public.issue_sanction('00000000-0000-4000-8000-000000000005',null,null,'registration','registration_restriction','restriction',now()+interval'1 hour')$$,'moderator issues restriction');select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);select throws_ok($$insert into public.tournament_players(tournament_id,user_id,ign,rating_status,registration_status)values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000005','blocked','pending','draft')$$,'P0001','REGISTRATION_RESTRICTED','active sanction enforced');
reset role;update public.sanctions set starts_at=now()-interval'2 hours',expires_at=now()-interval'1 second'where user_id='00000000-0000-4000-8000-000000000005';set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);select is((select count(*)::integer from public.get_own_active_sanctions()),0,'expired sanction does not remain active');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);select ok((select count(*)from public.audit_events where event_type in('PLATFORM_ROLE_GRANTED','RULE_VERSION_PUBLISHED','MAINTENANCE_MODE_CHANGED','SANCTION_ISSUED'))>=5,'sensitive actions audited');select is((select count(*)from public.platform_admins where status='active'),4::bigint,'role state canonical');select ok((select count(*)from public.retention_policies)=5,'retention metadata configured');select ok((select value='false'::jsonb from public.platform_config where key='maintenance_mode'),'maintenance restored');
select * from finish();rollback;
